1	/****************************************************************************
2	 * apps/examples/uvc_test/uvc_test.c
3	 *
4	 * USB Camera (UVC) live preview on framebuffer/LCD
5	 * Captures YUYV frames and displays them on /dev/lcd0 in real time.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <errno.h>
13	#include <fcntl.h>
14	#include <unistd.h>
15	#include <syslog.h>
16	#include <sys/ioctl.h>
17	#include <sys/time.h>
18	
19	#include <nuttx/video/video.h>
20	#include <nuttx/video/v4l2_cap.h>
21	#include <nuttx/video/fb.h>
22	#include <nuttx/lcd/lcd_dev.h>
23	
24	/****************************************************************************
25	 * Pre-processor Definitions
26	 ****************************************************************************/
27	
28	#define VIDEO_DEV_PATH    "/dev/video"
29	#define FB_DEV_PATH       "/dev/lcd0"
30	#define TEST_WIDTH        320
31	#define TEST_HEIGHT       240
32	#define TEST_BUF_COUNT    6   /* Deeper queue: more vacant buffers for the UVC
33	                               * stream thread to rotate through, so it never
34	                               * wraps onto the buffer the app is copying out.
35	                               */
36	#define PREVIEW_FRAMES    300   /* ~10s at 30fps; 0 = run forever */
37	#define SAVE_FRAMES       10    /* Save first N frames as .yuv files to /data/ */
38	
39	/****************************************************************************
40	 * Private Types
41	 ****************************************************************************/
42	
43	struct v_buffer
44	{
45	  uint8_t *start;
46	  uint32_t length;
47	};
48	
49	/****************************************************************************
50	 * Private Data
51	 ****************************************************************************/
52	
53	static struct fb_videoinfo_s g_vinfo;
54	static int                   g_fbfd = -1;
55	static int                   g_recfd = -1;  /* /data/capture.yuv */
56	static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];
57	
58	/* Private snapshot of one captured frame (YUYV), so the shared V4L2 capture
59	 * buffer can be requeued immediately and not be overwritten mid-processing.
60	 */
61	
62	static uint8_t               g_framecopy[TEST_WIDTH * TEST_HEIGHT * 2];
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	/* Clamp an int to [0,255] */
69	
70	static inline uint8_t clamp8(int v)
71	{
72	  if (v < 0)
73	    {
74	      return 0;
75	    }
76	
77	  if (v > 255)
78	    {
79	      return 255;
80	    }
81	
82	  return (uint8_t)v;
83	}
84	
85	/****************************************************************************
86	 * Name: fb_open
87	 *
88	 * Description:
89	 *   Open the framebuffer device and query its geometry.
90	 *
91	 ****************************************************************************/
92	
93	static int fb_open(void)
94	{
95	  int ret;
96	
97	  g_fbfd = open(FB_DEV_PATH, O_RDWR);
98	  if (g_fbfd < 0)
99	    {
100	      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
101	      return -errno;
102	    }
103	
104	  /* /dev/lcd0 is an lcddev character device, use LCDDEVIO_GETVIDEOINFO */
105	
106	  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
107	  if (ret < 0)
108	    {
109	      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
110	      close(g_fbfd);
111	      g_fbfd = -1;
112	      return -errno;
113	    }
114	
115	  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
116	
117	  /* Also emit to syslog so it lands in the serial log for diagnosis. */
118	
119	  syslog(LOG_ERR, "UVCTEST LCD: xres=%u yres=%u fmt=%u\n",
120	         g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
121	
122	  return OK;
123	}
124	
125	/****************************************************************************
126	 * Name: fb_update
127	 *
128	 * Description:
129	 *   Notify the framebuffer driver that the content changed (for LCD
130	 *   drivers that need an explicit flush).
131	 *
132	 ****************************************************************************/
133	
134	static void fb_blit(uint32_t w, uint32_t h)
135	{
136	  struct lcddev_area_s area;
137	
138	  memset(&area, 0, sizeof(area));
139	  area.row_start = 0;
140	  area.row_end   = h - 1;
141	  area.col_start = 0;
142	  area.col_end   = w - 1;
143	  area.stride    = w * 2;          /* RGB565: 2 bytes/pixel */
144	  area.data      = (FAR uint8_t *)g_rgbbuf;
145	
146	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
147	}
148	
149	/****************************************************************************
150	 * Name: yuyv_to_fb
151	 *
152	 * Description:
153	 *   Convert a YUYV 4:2:2 frame to the framebuffer's RGB565 format and
154	 *   blit it centered on the screen.
155	 *
156	 ****************************************************************************/
157	
158	static void yuyv_to_fb(FAR const uint8_t *yuyv, uint32_t len)
159	{
160	  /* The camera frame is TEST_WIDTH x TEST_HEIGHT (320x240).  The panel may be
161	   * narrower/taller (e.g. ILI9341 is 240x320 portrait).  Blit only the region
162	   * that fits BOTH the camera frame and the panel, and use the panel width as
163	   * the row stride so each source row lands at the correct column on screen.
164	   * Writing 320-wide rows to a 240-wide panel is exactly what produced the
165	   * diagonal "stripe/tear" artifact.
166	   */
167	
168	  uint32_t panel_w = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
169	  uint32_t panel_h = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
170	  uint32_t cpw = (panel_w < TEST_WIDTH)  ? panel_w : TEST_WIDTH;
171	  uint32_t cph = (panel_h < TEST_HEIGHT) ? panel_h : TEST_HEIGHT;
172	  uint32_t x;
173	  uint32_t y;
174	
175	  /* Each YUYV macro-pixel (4 bytes) encodes two pixels: Y0 U Y1 V.
176	   * The RGB565 destination is packed at the panel width (cpw) so the blit
177	   * stride matches the panel exactly.
178	   */
179	
180	  for (y = 0; y < cph; y++)
181	    {
182	      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
183	      FAR uint16_t *dst = &g_rgbbuf[y * cpw];
184	
185	      if ((size_t)(y * TEST_WIDTH * 2) + cpw * 2 > len)
186	        {
187	          break;  /* Frame shorter than expected; stop early */
188	        }
189	
190	      for (x = 0; x + 1 < cpw; x += 2)
191	        {
192	          int y0 = src[0];
193	          int u  = src[1] - 128;
194	          int y1 = src[2];
195	          int v  = src[3] - 128;
196	          int r;
197	          int g;
198	          int b;
199	
200	          /* YUV -> RGB (BT.601) */
201	
202	          r = y0 + ((179 * v) >> 7);
203	          g = y0 - ((44 * u) >> 7) - ((91 * v) >> 7);
204	          b = y0 + ((227 * u) >> 7);
205	          dst[x] = ((clamp8(r) & 0xf8) << 8) |
206	                   ((clamp8(g) & 0xfc) << 3) |
207	                   (clamp8(b) >> 3);
208	
209	          r = y1 + ((179 * v) >> 7);
210	          g = y1 - ((44 * u) >> 7) - ((91 * v) >> 7);
211	          b = y1 + ((227 * u) >> 7);
212	          dst[x + 1] = ((clamp8(r) & 0xf8) << 8) |
213	                       ((clamp8(g) & 0xfc) << 3) |
214	                       (clamp8(b) >> 3);
215	
216	          src += 4;
217	        }
218	    }
219	
220	  fb_blit(cpw, cph);
221	}
222	
223	/****************************************************************************
224	 * Public Functions
225	 ****************************************************************************/
226	
227	int uvc_test_main(int argc, char *argv[])
228	{
229	  struct v4l2_format fmt;
230	  struct v4l2_requestbuffers req;
231	  struct v4l2_buffer buf;
232	  struct v_buffer *buffers;
233	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
234	  int fd;
235	  int ret;
236	  int i;
237	  int frames = 0;
238	
239	  printf("=== USB Camera (UVC) Live Preview ===\n");
240	
241	  /* Open the framebuffer for display */
242	
243	  ret = fb_open();
244	  if (ret < 0)
245	    {
246	      printf("ERROR: framebuffer init failed\n");
247	      return ERROR;
248	    }
249	
250	  /* DIAG: draw a static test pattern (colored horizontal bars) once, before
251	   * any camera data, to isolate the blit/LCD path from the camera data.  If
252	   * these bars appear clean and aligned, the LCD geometry+blit is correct and
253	   * any stripes are in the camera-frame layout; if the bars themselves are
254	   * striped/torn, the problem is in the blit or LCD driver path.
255	   */
256	
257	  {
258	    uint32_t pw = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
259	    uint32_t ph = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
260	    uint32_t xx;
261	    uint32_t yy;
262	
263	    if (pw > TEST_WIDTH)  pw = TEST_WIDTH;
264	    if (ph > TEST_HEIGHT) ph = TEST_HEIGHT;
265	
266	    for (yy = 0; yy < ph; yy++)
267	      {
268	        uint16_t color;
269	        if      (yy < ph / 4)     color = 0xf800;  /* red    */
270	        else if (yy < ph / 2)     color = 0x07e0;  /* green  */
271	        else if (yy < ph * 3 / 4) color = 0x001f;  /* blue   */
272	        else                      color = 0xffff;  /* white  */
273	
274	        for (xx = 0; xx < pw; xx++)
275	          {
276	            g_rgbbuf[yy * pw + xx] = color;
277	          }
278	      }
279	
280	    fb_blit(pw, ph);
281	    syslog(LOG_ERR, "UVCTEST testpattern blitted %ux%u\n", pw, ph);
282	    sleep(2);
283	  }
284	
285	  /* Initialize video driver (creates /dev/video device) */
286	
287	  ret = capture_initialize(VIDEO_DEV_PATH);
288	  if (ret != 0)
289	    {
290	      printf("ERROR: Failed to initialize video: %d (errno=%d)\n", ret, errno);
291	      return ERROR;
292	    }
293	
294	  fd = open(VIDEO_DEV_PATH, O_RDWR);
295	  if (fd < 0)
296	    {
297	      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
298	      return ERROR;
299	    }
300	
301	  /* Set YUYV format */
302	
303	  memset(&fmt, 0, sizeof(fmt));
304	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
305	  fmt.fmt.pix.width = TEST_WIDTH;
306	  fmt.fmt.pix.height = TEST_HEIGHT;
307	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
308	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
309	
310	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
311	  if (ret < 0)
312	    {
313	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
314	      goto err_close;
315	    }
316	
317	  if (fmt.fmt.pix.sizeimage == 0)
318	    {
319	      fmt.fmt.pix.sizeimage = TEST_WIDTH * TEST_HEIGHT * 2;
320	    }
321	
322	  /* Request buffers */
323	
324	  memset(&req, 0, sizeof(req));
325	  req.count = TEST_BUF_COUNT;
326	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
327	  req.memory = V4L2_MEMORY_USERPTR;
328	
329	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
330	  if (ret < 0)
331	    {
332	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
333	      goto err_close;
334	    }
335	
336	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
337	  if (buffers == NULL)
338	    {
339	      printf("ERROR: Failed to allocate buffer array\n");
340	      goto err_close;
341	    }
342	
343	  for (i = 0; i < req.count; i++)
344	    {
345	      buffers[i].length = fmt.fmt.pix.sizeimage;
346	      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
347	      if (buffers[i].start == NULL)
348	        {
349	          printf("ERROR: Failed to allocate buffer %d\n", i);
350	          goto err_free_buffers;
351	        }
352	
353	      memset(&buf, 0, sizeof(buf));
354	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
355	      buf.memory = V4L2_MEMORY_USERPTR;
356	      buf.index = i;
357	      buf.m.userptr = (uintptr_t)buffers[i].start;
358	      buf.length = buffers[i].length;
359	
360	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
361	      if (ret < 0)
362	        {
363	          printf("ERROR: VIDIOC_QBUF failed for buffer %d: %d\n", i, errno);
364	          goto err_free_buffers;
365	        }
366	    }
367	
368	  /* Start streaming */
369	
370	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
371	  if (ret < 0)
372	    {
373	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
374	      goto err_free_buffers;
375	    }
376	
377	  printf("Live preview started (press Ctrl-C to stop)\n");
378	
379	  /* Preview loop */
380	
381	  while (PREVIEW_FRAMES == 0 || frames < PREVIEW_FRAMES)
382	    {
383	      memset(&buf, 0, sizeof(buf));
384	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
385	      buf.memory = V4L2_MEMORY_USERPTR;
386	
387	      ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
388	      if (ret < 0)
389	        {
390	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
391	          break;
392	        }
393	
394	      /* Snapshot the frame into a private buffer, then IMMEDIATELY requeue
395	       * the V4L2 buffer.  The UVC stream thread writes the next frame into
396	       * one of the shared capture buffers concurrently; if the app kept a
397	       * buffer for the whole convert+SPI-blit time (slow, per-row SPI), the
398	       * driver could wrap around and overwrite the buffer mid-read, showing
399	       * up as a moving horizontal "tear" band.  Copying out fast (one memcpy)
400	       * and requeuing at once shrinks that window to almost nothing.
401	       */
402	
403	      {
404	        uint32_t n = buf.bytesused;
405	        if (n > sizeof(g_framecopy))
406	          {
407	            n = sizeof(g_framecopy);
408	          }
409	
410	        memcpy(g_framecopy, (const void *)buf.m.userptr, n);
411	
412	        /* Requeue immediately, before the slow convert + blit. */
413	
414	        ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
415	        if (ret < 0)
416	          {
417	            printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
418	            break;
419	          }
420	
421	      /* Capture exactly ONE exact-size frame and display it.
422	       * This confirms whether a single 153600-byte frame renders
423	       * cleanly on the LCD (no stripes from SPI tearing).
424	       */
425	
426	      if (n >= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 * 95 / 100) &&
427	          n <= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 + 4096))
428	        {
429	          /* DIAG: check if row stride really is 640 bytes.
430	           * Dump first 8 bytes of row 0, row 1, row 2 at their
431	           * expected positions (640 bytes apart).  If row 1 starts
432	           * with non-YUYV values, the stride is wrong.
433	           */
434	
435	          /* DIAG: scan rows for YUYV continuity.  In a valid YUYV frame,
436	           * the Y value of pixel 0 in adjacent rows should be similar.
437	           * A sudden jump in Y0 indicates a row-boundary misalignment
438	           * in the assembled data.
439	           */
440	
441	          FAR const uint8_t *p = g_framecopy;
442	          uint32_t y;
443	          int prev_y0 = -1;
444	          int breaks = 0;
445	
446	          for (y = 0; y < TEST_HEIGHT; y++)
447	            {
448	              int y0 = p[y * TEST_WIDTH * 2];  /* Y of first pixel */
449	              if (prev_y0 >= 0 && abs(y0 - prev_y0) > 40)
450	                {
451	                  breaks++;
452	                  if (breaks <= 5)
453	                    {
454	                      syslog(LOG_ERR,
455	                        "ROW BREAK at y=%d: prev_Y=%d cur_Y=%d\n",
456	                        y, prev_y0, y0);
457	                    }
458	                }
459	              prev_y0 = y0;
460	            }
461	
462	          syslog(LOG_ERR, "ROW SCAN: %u rows, %d breaks\n",
463	                 TEST_HEIGHT, breaks);
464	
465	          /* Save this exact frame to file so we can compare PC vs LCD */
466	
467	          {
468	            int fd2 = open("/data/thisframe.yuv",
469	                           O_WRONLY | O_CREAT | O_TRUNC, 0666);
470	            if (fd2 >= 0)
471	              {
472	                write(fd2, g_framecopy, n);
473	                close(fd2);
474	                syslog(LOG_ERR, "Saved /data/thisframe.yuv (%u bytes)\n", n);
475	              }
476	          }
477	
478	          yuyv_to_fb(g_framecopy, n);
479	          syslog(LOG_ERR, "UVCTEST: single frame displayed (%u bytes)\n", n);
480	          break;  /* Display the frame and exit */
481	        }
482	
483	      }
484	    }
485	
486	  /* Stop streaming */
487	
488	  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
489	  printf("Preview stopped after %d frames\n", frames);
490	
491	  ret = OK;
492	
493	err_free_buffers:
494	  for (i = 0; i < req.count; i++)
495	    {
496	      if (buffers[i].start != NULL)
497	        {
498	          free(buffers[i].start);
499	        }
500	    }
501	
502	  free(buffers);
503	
504	err_close:
505	  close(fd);
506	  if (g_fbfd >= 0)
507	    {
508	      close(g_fbfd);
509	    }
510	
511	  return ret;
512	}
513

1051	static void usbhost_uvc_process_payload(FAR struct usbhost_uvc_s *priv,
1052	                                        FAR const uint8_t *payload,
1053	                                        size_t len)
1054	{
1055	  FAR const struct uvc_payload_header_s *header;
1056	  uint8_t header_len;
1057	  size_t data_len;
1058	  uint8_t fid;
1059	
1060	  if (len < 2)
1061	    {
1062	      return;
1063	    }
1064	
1065	  header = (FAR const struct uvc_payload_header_s *)payload;
1066	  header_len = header->bHeaderLength;
1067	  fid = header->bmHeaderInfo & UVC_HEADER_FID;
1068	
1069	  if (header_len > len)
1070	    {
1071	      return;
1072	    }
1073	
1074	  data_len = len - header_len;
1075	
1076	  /* DIAG: track payload data sizes within the frame being assembled.
1077	   * If any payload has data_len != 788 (full payload = 800-12), the
1078	   * cumulative offset shifts and produces the row-misalignment stripes.
1079	   */
1080	
1081	  {
1082	    static uint32_t non788;
1083	    static uint32_t total;
1084	    static bool     once;
1085	
1086	    total++;
1087	    if (data_len > 0 && data_len != 788)
1088	      {
1089	        non788++;
1090	        if (!once && priv->frame_offset > 100000)
1091	          {
1092	            once = true;
1093	            syslog(LOG_ERR, "NON788: data_len=%zu at frame_offset=%zu "
1094	                   "(total=%u non788=%u)\n",
1095	                   data_len, priv->frame_offset, total, non788);
1096	          }
1097	      }
1098	
1099	    if ((total % 2000) == 0)
1100	      {
1101	        syslog(LOG_ERR, "PLDIST: total=%u non788=%u (%.1f%%)\n",
1102	               total, non788, non788 * 100.0f / total);
1103	      }
1104	  }
1105	
1106	  /* DIAG: per-second throughput counter and EOF-to-EOF span measurement.
1107	   * Prints once per second: payloads/sec, data bytes/sec, total assembled
1108	   * bytes since last print, and how many EOFs were seen.
1109	   */
1110	
1111	  {
1112	    static uint32_t span_bytes;
1113	    static uint32_t span_fidflips;
1114	    static uint8_t  span_fid = 0xff;
1115	    static uint32_t sec_pls;      /* payloads this second */
1116	    static uint32_t sec_bytes;    /* data bytes this second */
1117	    static uint32_t sec_eofs;     /* EOFs this second */
1118	    static int      scnt;
1119	
1120	    bool eof = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;
1121	
1122	    sec_pls++;
1123	    sec_bytes += data_len;
1124	    if (eof) sec_eofs++;
1125	
1126	    /* Every 2000 payloads (~1/3 sec at 6000/s), log cumulative throughput. */
1127	
1128	    if ((sec_pls % 2000) == 0)
1129	      {
1130	        syslog(LOG_ERR,
1131	          "TP: pls=%u bytes=%u eofs=%u\n",
1132	          sec_pls, sec_bytes, sec_eofs);
1133	      }
1134	
1135	    if (span_fid != 0xff && fid != span_fid)
1136	      {
1137	        span_fidflips++;
1138	      }
1139	
1140	    span_fid = fid;
1141	    span_bytes += data_len;
1142	
1143	    if (eof)
1144	      {
1145	        if ((scnt++ % 30) == 0)
1146	          {
1147	            syslog(LOG_ERR, "SPAN(eof2eof): bytes=%u fidflips=%u\n",
1148	                   span_bytes, span_fidflips);
1149	          }
1150	
1151	        span_bytes = 0;
1152	        span_fidflips = 0;
1153	      }
1154	  }
1155	
1156	  /* Frame delimiting — dual EOF + FID with size gate (Linux UVC style).
1157	   *
1158	   * This camera toggles FID 11-35 times per frame and fires EOF at
1159	   * unpredictable byte positions.  The strategy:
1160	   *
1161	   *  1. FID toggle → deliver current frame (if ≥95% of expected size),
1162	   *     then reset.  This is the primary delimiter: each FID value
1163	   *     represents a distinct time window of camera data.
1164	   *
1165	   *  2. EOF → also deliver (if ≥95%), then reset.  This catches frames
1166	   *     where FID didn't toggle at the boundary.
1167	   *
1168	   *  3. Size gate: ≥95% of max_frame_size (Linux reference threshold).
1169	   *     Frames below this are dropped (partial/too short).
1170	   *
