1243	static int usbhost_uvc_stream_thread(int argc, FAR char *argv[])
1244	{
1245	  FAR struct usbhost_uvc_s *priv;
1246	  FAR struct usbhost_hubport_s *hport;
1247	  FAR struct usbhost_driver_s *drvr;
1248	  ssize_t nbytes;
1249	
1250	  priv = (FAR struct usbhost_uvc_s *)
1251	    ((uintptr_t)strtoul(argv[1], NULL, 16));
1252	
1253	  DEBUGASSERT(priv != NULL);
1254	  hport = priv->usbclass.hport;
1255	  DEBUGASSERT(hport != NULL && hport->drvr != NULL);
1256	  drvr = hport->drvr;
1257	
1258	  syslog(LOG_ERR, "UVC stream thread started, waiting for endpoint\n");
1259	
1260	  /* Wait for SET_INTERFACE to enable the streaming endpoint */
1261	
1262	  nxsem_wait_uninterruptible(&priv->stream_sem);
1263	
1264	  syslog(LOG_ERR, "UVC stream thread: endpoint ready, starting transfers\n");
1265	
1266	  while (!priv->disconnected && priv->streaming)
1267	    {
1268	      /* Receive isochronous data */
1269	
1270	      nbytes = DRVR_TRANSFER(drvr, priv->ep_stream,
1271	                             priv->xfer_buf, priv->xfer_buflen);
1272	
1273	      if (nbytes > 0)
1274	        {
1275	          /* The EHCI ISOC driver returns a batch of payloads framed as
1276	           * [u16 LE length][payload bytes] repeated.  Split them back apart
1277	           * and process each individually — process_payload expects one
1278	           * payload (with its own 12-byte UVC header) at a time.  Batching
1279	           * is what lets the consumer keep up with the controller's fill
1280	           * rate; see the serve logic in ehci-driver.c sunxi_ioc_wait().
1281	           */
1282	
1283	          size_t off = 0;
1284	
1285	          while (off + 2 <= (size_t)nbytes)
1286	            {
1287	              uint16_t plen = (uint16_t)priv->xfer_buf[off] |
1288	                              ((uint16_t)priv->xfer_buf[off + 1] << 8);
1289	              off += 2;
1290	
1291	              if (plen == 0 || off + plen > (size_t)nbytes)
1292	                {
1293	                  /* Truncated/garbage framing — stop to avoid misreading. */
1294	
1295	                  break;
1296	                }
1297	
1298	              usbhost_uvc_process_payload(priv, priv->xfer_buf + off, plen);
1299	              off += plen;
1300	            }
1301	        }
1302	      else if (nbytes < 0)
1303	        {
1304	          if (nbytes == -EAGAIN || nbytes == -ETIMEDOUT)
1305	            {
1306	              nxsig_usleep(1000);
1307	              continue;
1308	            }
1309	
1310	          syslog(LOG_ERR, "UVC stream: transfer error %zd\n", nbytes);
1311	
1312	          if (nbytes == -ENODEV || nbytes == -EPIPE)
1313	            {
1314	              break;
1315	            }
1316	
1317	          /* On transient errors (EIO/XACTERR), wait before retrying
1318	           * to avoid overwhelming the device.
1319	           */
1320	
1321	          nxsig_usleep(5000);  /* 5ms */
1322	        }
1323	    }
1324	
1325	  syslog(LOG_ERR, "UVC stream thread exiting\n");
1326	  priv->stream_tid = 0;
1327	  return OK;
1328	}
