/* (1) If we have buffered payloads, pack as many as fit into
 * the caller buffer, framed as [u16 LE len][payload] repeated.
 * The UVC stream thread (usbhost_uvc_stream_thread) splits this
 * batch back into individual payloads.  Batching lets the
 * consumer drain the FIFO much faster than one-payload-per-call,
 * keeping up with the controller's ~6000 payload/sec fill rate.
 *
 * NOTE: this wire-format MUST match the de-framer in
 * usbhost_uvc.c; the two are a contract.
 */

if (g_ring.f_cnt > 0)
  {
    size_t packed = 0;

    while (g_ring.f_cnt > 0)
      {
        uint32_t len = g_ring.fifo_len[g_ring.f_head];
        uint32_t seq = g_ring.fifo_seq[g_ring.f_head];
        uint8_t *src = g_ring.fifo +
                       (size_t)g_ring.f_head * ISOC_FIFO_SLOTSZ;

        /* Clamp a single payload to the FIFO slot size so the
         * 2-byte length prefix can never overflow u16.
         */

        if (len > ISOC_FIFO_SLOTSZ)
          {
            len = ISOC_FIFO_SLOTSZ;
          }

        /* Stop if this [u16 len][payload] entry won't fit in the
         * remaining caller buffer.  Leave the payload in the FIFO
         * for the next DRVR_TRANSFER (f_head NOT advanced).
         */

        if (packed + 2 + len > g_ring.user_buflen)
          {
            break;
          }

        /* DIAG: check sequence continuity (per payload).  If seq
         * jumps backward or gaps, payloads are arriving out of
         * order from the ring.
         */

        {
          static uint32_t last_seq = 0xffffffff;
          static uint32_t reorder_cnt;

          if (last_seq != 0xffffffff && seq != last_seq + 1)
            {
              if ((reorder_cnt++ % 50) == 0)
                {
                  syslog(LOG_ERR,
                    "REORDER: expected=%u got=%u delta=%d #%u\n",
                    last_seq + 1, seq,
                    (int)(seq - last_seq - 1), reorder_cnt);
                }
            }

          last_seq = seq;
        }

        /* Write the 2-byte little-endian length prefix, then the
         * payload bytes.
         */

        g_ring.user_buf[packed]     = (uint8_t)(len & 0xff);
        g_ring.user_buf[packed + 1] =
          (uint8_t)((len >> 8) & 0xff);
        memcpy(g_ring.user_buf + packed + 2, src, len);
        packed += 2 + len;

        g_ring.f_head = (g_ring.f_head + 1) % ISOC_FIFO_SLOTS;
        g_ring.f_cnt--;
      }

    /* Return the packed batch.  packed can only be 0 if the
     * caller buffer is too small to hold even one entry (never
     * happens: user_buflen = CONFIG_USBHOST_UVC_BUFSIZE = 32768,
     * far larger than 2 + 800); in that pathological case fall
     * through to harvest rather than return an empty transfer.
     */

    if (packed > 0)
      {
        epinfo->xfrd    = packed;
        epinfo->result  = OK;
        epinfo->iocwait = false;
        return epinfo->result;
      }
  }

