  /* Frame delimiting — dual EOF + FID with size gate (Linux UVC style).
   *
   * This camera toggles FID 11-35 times per frame and fires EOF at
   * unpredictable byte positions.  The strategy:
   *
   *  1. FID toggle → deliver current frame (if ≥95% of expected size),
   *     then reset.  This is the primary delimiter: each FID value
   *     represents a distinct time window of camera data.
   *
   *  2. EOF → also deliver (if ≥95%), then reset.  This catches frames
   *     where FID didn't toggle at the boundary.
   *
   *  3. Size gate: ≥95% of max_frame_size (Linux reference threshold).
   *     Frames below this are dropped (partial/too short).
   *
   *  4. Max-size safety: if frame_offset reaches max_frame_size, deliver
   *     immediately to prevent merging two frames.
   */

  /* Append data to frame buffer.  FID is tracked for DIAG only; it does NOT
   * trigger delivery — this camera toggles FID ~20 times per frame, so
   * FID-based delimiting would fragment each frame into tiny pieces.
   */

  UNUSED(fid);

  /* Append data to frame buffer */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* (c) Deliver on EOF (primary) or max_frame_size (safety).
   *
   * EOF fires near the true frame boundary on most cameras.  Accept frames
   * with ≥95% of expected size (Linux reference threshold) to handle the
   * camera's occasional early/late EOF.  Max-size delivery catches the case
   * where EOF is missed entirely.
   *
   * FID is NOT used — this camera toggles it ~20 times per frame.
   */

  /* EOF: deliver if ≥95% complete, ALWAYS reset. */

  if (header->bmHeaderInfo & UVC_HEADER_EOF)
    {
      /* DIAG: log the assembled size at EVERY EOF (whether or not it meets
       * the 95% gate).  If every frame lands short by ~1 iTD worth of data
       * (~4-6KB), the culprit is ring lapping (controller overwrites an iTD
       * before harvest); if sizes swing wildly, EOF is firing early.  Print
       * the first ~40 EOFs then go quiet.
       */

      {
        static uint32_t eofn;

        if (eofn++ < 40)
          {
            uint32_t pct = priv->max_frame_size ?
              (uint32_t)((uint64_t)priv->frame_offset * 100 /
                         priv->max_frame_size) : 0;
            syslog(LOG_ERR, "EOFSZ #%u: offset=%zu / %u (%u%%) %s\n",
                   eofn, priv->frame_offset,
                   (unsigned int)priv->max_frame_size, pct,
                   (priv->frame_offset >=
                    (priv->max_frame_size * 95 / 100)) ? "DELIVER" : "drop");
          }
      }

      if (priv->max_frame_size > 0 &&
          priv->frame_offset >= (priv->max_frame_size * 95 / 100) &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->frame_offset;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  /* Max-size safety: deliver if we've reached the expected frame size. */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      if (priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->max_frame_size;
