  /* Frame delimiting — FID toggle primary, EOF secondary (Linux UVC style,
   * drivers/media/usb/uvc/uvc_video.c).
   *
   * Verified by PLTRACE on this camera (after skipping the startup burst of
   * empty payloads that had polluted earlier measurements): on real DATA
   * payloads the FID bit holds steady for an entire frame (~195 payloads,
   * 153600 bytes) and flips exactly once at the frame boundary; the last
   * payload of a frame additionally carries EOF.  The earlier "FID toggles
   * ~20x per frame" observation was an artifact of empty payloads and (before
   * batch consumption) ring-lapping reorder — both now eliminated.
   *
   * Algorithm:
   *   1. FID change vs the last assembling payload => the previous frame
   *      ended on the previous payload.  Deliver it (if it reached the size
   *      gate) and start a fresh frame with THIS payload's data.  This keeps
   *      every frame aligned to the true FID boundary, so the assembled data
   *      never spans two frames (the root cause of the tear/misalignment).
   *   2. EOF flag => the current payload is the last of its frame; append it,
   *      then deliver and reset.  Acts as a secondary boundary in case a FID
   *      flip is ever missed.
   *   3. Size gate: only deliver frames that reached >= 50% of max_frame_size,
   *      dropping startup fragments and short/corrupt frames (avoids flicker).
   *   4. Max-size safety: never overrun the assembly buffer.
   */

  {
    uint8_t curfid = fid;

    /* (1) FID edge: the previous frame is complete.  Deliver it, then this
     * payload becomes the first of the new frame.  asm_lastfid == 0xff means
     * we have not started assembling yet (first payload after start), so no
     * previous frame to deliver.
     */

    if (priv->asm_lastfid != 0xff && curfid != priv->asm_lastfid)
      {
        if (priv->frame_offset >= (priv->max_frame_size / 2) &&
            priv->capture_cb != NULL && priv->user_buf != NULL)
          {
            size_t copy_len = priv->frame_offset;
            if (copy_len > priv->user_buflen)
              {
                copy_len = priv->user_buflen;
              }

            memcpy(priv->user_buf, priv->frame_buf, copy_len);
            priv->capture_cb(0, copy_len, 0, priv->capture_arg);
          }

        priv->frame_offset = 0;  /* Start the new frame (this payload) fresh */
      }

    priv->asm_lastfid = curfid;
  }

  /* (2) Append this payload's data to the current frame. */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* (3) EOF: this payload is the last of its frame.  Deliver (subject to the
   * size gate) and reset.  Secondary to the FID edge above.
   */

  if (header->bmHeaderInfo & UVC_HEADER_EOF)
    {
      if (priv->frame_offset >= (priv->max_frame_size / 2) &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->frame_offset;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }

  /* (4) Max-size safety: if we somehow reach the full frame size without a
   * boundary marker, deliver to prevent overrunning into the next frame.
   */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      if (priv->capture_cb != NULL && priv->user_buf != NULL)
        {
          size_t copy_len = priv->max_frame_size;
          if (copy_len > priv->user_buflen)
            {
              copy_len = priv->user_buflen;
            }

          memcpy(priv->user_buf, priv->frame_buf, copy_len);
          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
        }

      priv->frame_offset = 0;
    }
}

