/* DIAG: raw per-payload trace of the first 300 NON-EMPTY payloads, printed
 * once.  The camera emits a long burst of empty (dlen=0) startup payloads
 * that flooded the previous trace, so skip dlen==0 here to see the header
 * bits on real data payloads.  A "|" marks any payload carrying EOF so the
 * frame cadence is easy to read.  Columns:
 *   idx   running non-empty payload index
 *   fid   Frame ID bit (0/1)
 *   eof   End-of-Frame bit
 *   err   Error bit (bit6)
 *   dlen  data bytes in this payload
 *   info  raw bmHeaderInfo byte (hex)
 * Read the fid column: if it holds steady for a long run (~195 data
 * payloads = one 153600-byte frame) then flips once, FID is the true frame
 * delimiter and framing should key off the FID edge.
 */

{
  static uint32_t traceN;

  if (data_len > 0 && traceN < 300)
    {
      bool eofb = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;
      syslog(LOG_ERR,
        "PLTRACE %u: fid=%u eof=%u err=%u dlen=%zu info=%02x %s\n",
        traceN,
        (unsigned)(header->bmHeaderInfo & UVC_HEADER_FID),
        (unsigned)(eofb ? 1 : 0),
        (unsigned)((header->bmHeaderInfo & UVC_HEADER_ERR) ? 1 : 0),
        data_len, (unsigned)header->bmHeaderInfo,
        eofb ? "<EOF" : "");
      traceN++;
    }
}

/* DIAG: characterise the FID toggle as a frame delimiter.  Now that ring
 * lapping is gone (ITDFILL empty_uf=0%), payloads arrive in order, so the
 * FID bit may again mark true frame boundaries.  Log how many data bytes
 * and payloads accumulated between consecutive FID flips, plus the EOF
 * flag on the flipping payload.  If the byte counts cluster near 153600,
 * FID is the correct delimiter and framing should switch to it.  Print the
 * first 40 flips then go quiet.
 */

{
  static uint8_t  fdiag_lastfid = 0xff;
  static uint32_t fdiag_bytes;
  static uint32_t fdiag_pls;
  static uint32_t fdiag_flips;

  bool eofbit = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;

  if (fdiag_lastfid != 0xff && fid != fdiag_lastfid)
    {
      if (fdiag_flips++ < 40)
        {
          syslog(LOG_ERR,
            "FIDSEG #%u: bytes=%u pls=%u eof=%d\n",
            fdiag_flips, fdiag_bytes, fdiag_pls, (int)eofbit);
        }

