}

/* DIAG: per-second throughput counter and EOF-to-EOF span measurement.
 * Prints once per second: payloads/sec, data bytes/sec, total assembled
 * bytes since last print, and how many EOFs were seen.
 */

{
  static uint32_t span_bytes;
  static uint32_t span_fidflips;
  static uint8_t  span_fid = 0xff;
  static uint32_t sec_pls;      /* payloads this second */
  static uint32_t sec_bytes;    /* data bytes this second */
  static uint32_t sec_eofs;     /* EOFs this second */
  static int      scnt;

  bool eof = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;

  sec_pls++;
  sec_bytes += data_len;
  if (eof) sec_eofs++;

  /* Every 2000 payloads (~1/3 sec at 6000/s), log cumulative throughput. */

  if ((sec_pls % 2000) == 0)
    {
      syslog(LOG_ERR,
        "TP: pls=%u bytes=%u eofs=%u\n",
        sec_pls, sec_bytes, sec_eofs);
    }

  if (span_fid != 0xff && fid != span_fid)
    {
      span_fidflips++;
    }

  span_fid = fid;
  span_bytes += data_len;

  if (eof)
    {
      if ((scnt++ % 30) == 0)
        {
          syslog(LOG_ERR, "SPAN(eof2eof): bytes=%u fidflips=%u\n",
                 span_bytes, span_fidflips);
        }

      span_bytes = 0;
      span_fidflips = 0;
    }
}

