 * within a single frame).  So:
 *   - EOF (bmHeaderInfo bit1) precisely marks the last payload of a frame.
 *   - FID (bit0) toggles mid-frame on this camera and MUST NOT delimit
 *     frames — keying off FID chops each frame into 2-3 pieces (the earlier
 *     "half-frame 76800B" symptom).
 *
 * Algorithm:
 *   1. Append this payload's data to the current frame.
 *   2. On EOF: the frame is complete — deliver it and reset.  A light size
 *      gate (>= 50% of max_frame_size) drops the startup burst of tiny/empty
 *      payloads and any obviously-corrupt short frame, without rejecting the
 *      normal frame-size jitter.
 *   3. Max-size safety: never overrun the assembly buffer / next frame.
 *
 * NOTE: an earlier revision used "FID toggle primary" based on a single-frame
 * PLTRACE window where FID happened to be stable; the multi-frame FIDBITS
 * capture disproved that.  Do not reintroduce FID-based delimiting.
 */

UNUSED(fid);

/* (1) Append this payload's data to the current frame. */

if (priv->frame_offset + data_len <= priv->frame_buflen)
  {
    memcpy(priv->frame_buf + priv->frame_offset,
           payload + header_len, data_len);
    priv->frame_offset += data_len;
  }

/* (2) EOF: this payload is the last of its frame.  Deliver (subject to the
 * size gate) and reset.  This is the sole primary frame boundary.
 */

if (header->bmHeaderInfo & UVC_HEADER_EOF)
  {
    if (priv->frame_offset >= (priv->max_frame_size / 2) &&
        priv->capture_cb != NULL && priv->user_buf != NULL)
      {
        size_t copy_len = priv->frame_offset;
        if (copy_len > priv->user_buflen)
          {
            copy_len = priv->user_buflen;
          }

        memcpy(priv->user_buf, priv->frame_buf, copy_len);
        priv->capture_cb(0, copy_len, 0, priv->capture_arg);
      }

    priv->frame_offset = 0;
  }

