  /* The camera frame is TEST_WIDTH x TEST_HEIGHT (320x240).  The panel may be
   * narrower/taller (e.g. ILI9341 is 240x320 portrait).  Blit only the region
   * that fits BOTH the camera frame and the panel, and use the panel width as
   * the row stride so each source row lands at the correct column on screen.
   * Writing 320-wide rows to a 240-wide panel is exactly what produced the
   * diagonal "stripe/tear" artifact.
   */

  uint32_t panel_w = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
  uint32_t panel_h = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
  uint32_t cpw = (panel_w < TEST_WIDTH)  ? panel_w : TEST_WIDTH;
  uint32_t cph = (panel_h < TEST_HEIGHT) ? panel_h : TEST_HEIGHT;
  uint32_t x;
  uint32_t y;

  /* Each YUYV macro-pixel (4 bytes) encodes two pixels: Y0 U Y1 V.
   * The RGB565 destination is packed at the panel width (cpw) so the blit
   * stride matches the panel exactly.
   */

  for (y = 0; y < cph; y++)
    {
      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
      FAR uint16_t *dst = &g_rgbbuf[y * cpw];

      if ((size_t)(y * TEST_WIDTH * 2) + cpw * 2 > len)
        {
          break;  /* Frame shorter than expected; stop early */
        }

      for (x = 0; x + 1 < cpw; x += 2)
        {
          int y0 = src[0];
          int u  = src[1] - 128;
          int y1 = src[2];
          int v  = src[3] - 128;
          int r;
          int g;
          int b;

          /* YUV -> RGB (BT.601) */

          r = y0 + ((179 * v) >> 7);
          g = y0 - ((44 * u) >> 7) - ((91 * v) >> 7);
          b = y0 + ((227 * u) >> 7);
          dst[x] = ((clamp8(r) & 0xf8) << 8) |
