       * sizes swing widely, EOF is firing at random offsets.  Runs for
       * PREVIEW_FRAMES then stops (no early break).
       */

      if (n >= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 * 50 / 100) &&
          n <= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 + 4096))
        {
          /* DIAG: scan rows for YUYV continuity.  In a valid YUYV frame,
           * the Y value of pixel 0 in adjacent rows should be similar.
           * A sudden jump in Y0 indicates a row-boundary misalignment
           * in the assembled data.
           */

          FAR const uint8_t *p = g_framecopy;
          uint32_t y;
          int prev_y0 = -1;
          int breaks = 0;
          int firstbreak = -1;

          for (y = 0; y < TEST_HEIGHT; y++)
            {
              int y0 = p[y * TEST_WIDTH * 2];  /* Y of first pixel */
              if (prev_y0 >= 0 && abs(y0 - prev_y0) > 40)
                {
                  breaks++;
                  if (firstbreak < 0)
                    {
                      firstbreak = (int)y;
                    }
                }
              prev_y0 = y0;
            }

          /* One compact line per frame: index, bytes, valid rows, break count
           * and the row of the first break.
           */

          syslog(LOG_ERR,
            "FRAME #%d: bytes=%u rows=%u breaks=%d firstbreak=%d\n",
            frames, n, n / (TEST_WIDTH * 2), breaks, firstbreak);

          /* Save the first EXACT full frame (153600 B) for PC-side analysis.
           * Attempt to correct the staircase shift. */

          {
            static int saved;

            if (!saved && n == (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2))
              {
                int fd2 = open("/data/full.yuv",
                               O_WRONLY | O_CREAT | O_TRUNC, 0666);
                if (fd2 >= 0)
                  {
                    write(fd2, g_framecopy, n);
                    close(fd2);
                    saved = 1;
                    syslog(LOG_ERR, "Saved /data/full.yuv (153600 B)\n");
                  }
              }
          }

          yuyv_to_fb(g_framecopy, n);
          frames++;
        }

      }
    }

