   *
   * Confirmed 2026-08-07 by存图: the camera sends one COMPLETE frame per EOF
   * (EOF-assembled full frame shows a single complete image), while FID
   * toggles several times *within* one frame (camera firmware quirk).  So EOF
   * = true frame end; FID must not delimit.  The residual "tearing" seen in
   * the EOF full frame is a separate byte-phase-shift issue being diagnosed
   * (see FRAMEHDR/append diagnostics), NOT a framing error.
   *
   * Algorithm:
   *   1. Append this payload's data to the current frame.
   *   2. On EOF: deliver (size gate >= 50%) and reset.
   *   3. Max-size safety: never overrun the assembly buffer / next frame.
   */

  UNUSED(fid);

  /* (1) Append this payload's data to the current frame. */

  if (priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }

  /* (2) EOF: last payload of its frame.  Deliver (size gate) and reset. */

  if (header->bmHeaderInfo & UVC_HEADER_EOF)
    {
      if (priv->frame_offset >= (priv->max_frame_size / 2) &&
          priv->capture_cb != NULL && priv->user_buf != NULL)
        {
