/* Frame delimiting — scan for JPEG SOI (FF D8 FF) anywhere in the
   * payload data.  SOI may appear mid-payload (e.g. after the previous
   * frame's EOI in the same packet).  When found, split: append bytes
   * before SOI to the current frame and deliver it, then start the new
   * frame with SOI and the bytes after it.
   */

  UNUSED(fid);

  {
    const uint8_t *data = payload + header_len;
    size_t remaining = data_len;

    while (remaining > 0)
      {
        /* Search for SOI (FF D8 FF) in remaining data. */

        const uint8_t *soi_ptr = NULL;
        size_t i;

        for (i = 0; i + 2 < remaining; i++)
          {
            if (data[i] == 0xff && data[i + 1] == 0xd8 &&
                data[i + 2] == 0xff)
              {
                soi_ptr = &data[i];
                break;
              }
          }

        if (soi_ptr != NULL && priv->frame_offset > 0)
          {
            /* Append bytes before SOI to current frame. */

            size_t before = (size_t)(soi_ptr - data);
            if (before > 0 &&
                priv->frame_offset + before <= priv->frame_buflen)
              {
                memcpy(priv->frame_buf + priv->frame_offset,
                       data, before);
                priv->frame_offset += before;
              }

            /* Deliver current frame. */

            if (priv->frame_offset >= 1024 &&
                priv->capture_cb != NULL && priv->user_buf != NULL)
              {
                size_t copy_len = priv->frame_offset;
                if (copy_len > priv->user_buflen)
                  copy_len = priv->user_buflen;
                memcpy(priv->user_buf, priv->frame_buf, copy_len);
                priv->capture_cb(0, copy_len, 0, priv->capture_arg);
              }

            priv->frame_offset = 0;

            /* Advance past the bytes we just consumed. */

            remaining -= (size_t)(soi_ptr - data);
            data = soi_ptr;
          }
        else if (soi_ptr != NULL && priv->frame_offset == 0)
          {
            /* First SOI ever (or after a reset).  Just start here. */

            remaining -= (size_t)(soi_ptr - data);
            data = soi_ptr;

            /* Fall through to append below. */

            if (priv->frame_offset + remaining <= priv->frame_buflen)
              {
                memcpy(priv->frame_buf + priv->frame_offset,
                       data, remaining);
                priv->frame_offset += remaining;
              }
            break;
          }
        else
          {
            /* No SOI found — append all remaining data to current frame. */

            if (priv->frame_offset + remaining <= priv->frame_buflen)
              {
                memcpy(priv->frame_buf + priv->frame_offset,
                       data, remaining);
                priv->frame_offset += remaining;
              }
            break;
          }
      }
  }

